import React from 'react';
import './Navbar.css';

interface NavbarProps {
  onAddRow: () => void;
  onSave: () => void;
}

const Navbar = ({ onAddRow, onSave }: NavbarProps) => {
  return (
    <nav className="floating-navbar">
      <span className="navbar-brand">Fleet</span>
      <div className="navbar-links">
        <button className="navbar-button" onClick={onAddRow}>+ Add Row</button>
        <button className="navbar-button navbar-button-primary" onClick={onSave}>Save</button>
      </div>
    </nav>
  );
};

export default Navbar;
